<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ArrowLeft, Bookmark, CalendarDays, Flag, Heart, MapPin, MessageCircle, Send, Share2, Trash2, Wallet } from 'lucide-vue-next'
import { createCommunityComment, getCommunityPost, reportCommunityContent, setCommunityFavorite, setCommunityLike, withdrawCommunityPost, type CommunityPost } from '../api'
import { useRoute, useRouter } from 'vue-router'

const route = useRoute()
const router = useRouter()
const post = ref<CommunityPost | null>(null)
const loading = ref(true)
const error = ref('')
const comment = ref('')
const submitting = ref(false)

async function load() { try { post.value = await getCommunityPost(Number(route.params.id)) } catch (exception) { error.value = exception instanceof Error ? exception.message : '帖子加载失败' } finally { loading.value = false } }
async function toggleLike() { if (!post.value) return; const active = !post.value.liked; try { await setCommunityLike(post.value.id, active); post.value.liked = active; post.value.like_count += active ? 1 : -1 } catch (exception) { error.value = exception instanceof Error ? exception.message : '操作失败' } }
async function toggleFavorite() { if (!post.value) return; const active = !post.value.favorited; try { await setCommunityFavorite(post.value.id, active); post.value.favorited = active; post.value.favorite_count += active ? 1 : -1 } catch (exception) { error.value = exception instanceof Error ? exception.message : '操作失败' } }
async function submitComment() { if (!post.value || !comment.value.trim()) return; submitting.value = true; try { const item = await createCommunityComment(post.value.id, comment.value.trim()); post.value.comments = [...(post.value.comments || []), item]; post.value.comment_count += 1; comment.value = '' } catch (exception) { error.value = exception instanceof Error ? exception.message : '评论发布失败' } finally { submitting.value = false } }
async function reportPost() { if (!post.value) return; const reason = window.prompt('请填写举报原因'); if (!reason?.trim()) return; try { await reportCommunityContent('post', post.value.id, reason.trim()); window.alert('举报已提交，管理员会尽快处理。') } catch (exception) { error.value = exception instanceof Error ? exception.message : '举报提交失败' } }
async function withdraw() { if (!post.value || !window.confirm('撤回后，其他用户将不能继续浏览这篇帖子。')) return; try { await withdrawCommunityPost(post.value.id); await router.push('/community') } catch (exception) { error.value = exception instanceof Error ? exception.message : '撤回失败' } }
async function copyLink() { await navigator.clipboard?.writeText(window.location.href); }
onMounted(() => { void load() })
</script>

<template>
  <div class="page-container community-detail-page">
    <RouterLink class="back-link" to="/community"><ArrowLeft :size="16" />返回旅行灵感</RouterLink>
    <div v-if="loading" class="loading-state">正在打开行程故事...</div>
    <div v-else-if="error && !post" class="empty-state"><MapPin :size="28" /><h2>{{ error }}</h2><RouterLink class="secondary-button" to="/community">返回社区</RouterLink></div>
    <template v-else-if="post">
      <section v-if="post.images.length" class="photo-gallery" :class="{ single: post.images.length === 1 }"><img v-for="image in post.images.slice(0, 5)" :key="image.id" :src="image.url" :alt="image.alt_text || `${post.city_name}旅行照片`" /></section>
      <section class="story-layout"><article class="story-main"><header class="story-header"><span class="eyebrow">{{ post.city_name }} · TRIP STORY</span><h1>{{ post.title }}</h1><p class="author-line">{{ post.author.name }} · {{ new Date(post.created_at).toLocaleDateString() }}</p></header><p v-if="post.body" class="story-body">{{ post.body }}</p><div class="trip-facts"><span><CalendarDays :size="16" />{{ post.itinerary.days }} 天</span><span><Wallet :size="16" />预算 ¥{{ post.itinerary.budget_total }}</span></div><section class="itinerary-section"><h2>{{ post.itinerary.title }}</h2><div v-for="day in post.itinerary.itinerary_days" :key="day.day_number" class="day-row"><div><b>DAY {{ String(day.day_number).padStart(2, '0') }}</b><span>{{ day.title }}</span></div><ol><li v-for="stop in day.stops" :key="`${stop.start_time}-${stop.name}`"><time>{{ stop.start_time }}</time><strong>{{ stop.name }}</strong><small>{{ stop.end_time }}</small></li></ol></div></section></article>
        <aside class="story-actions" aria-label="帖子互动"><button :class="{ active: post.liked }" title="点赞" aria-label="点赞" @click="toggleLike"><Heart :size="19" :fill="post.liked ? 'currentColor' : 'none'" /><span>{{ post.like_count }}</span></button><button :class="{ active: post.favorited }" title="收藏" aria-label="收藏" @click="toggleFavorite"><Bookmark :size="19" :fill="post.favorited ? 'currentColor' : 'none'" /><span>{{ post.favorite_count }}</span></button><button title="复制链接" aria-label="复制链接" @click="copyLink"><Share2 :size="19" /><span>分享</span></button><button title="举报帖子" aria-label="举报帖子" @click="reportPost"><Flag :size="19" /><span>举报</span></button><button v-if="post.can_manage" class="danger" title="撤回帖子" aria-label="撤回帖子" @click="withdraw"><Trash2 :size="19" /><span>撤回</span></button></aside></section>
      <p v-if="error" class="form-error">{{ error }}</p>
      <section class="comments-section"><div class="section-heading"><div><span class="eyebrow">COMMENTS</span><h2>{{ post.comment_count }} 条评论</h2></div><MessageCircle :size="20" class="comment-icon" /></div><form class="comment-form" @submit.prevent="submitComment"><textarea v-model="comment" rows="4" maxlength="1000" placeholder="写下你的想法" /><button class="primary-button" :disabled="submitting || !comment.trim()" type="submit"><Send :size="16" />{{ submitting ? '发布中...' : '发表评论' }}</button></form><div v-if="post.comments?.length" class="comment-list"><article v-for="item in post.comments" :key="item.id"><header><strong>{{ item.author.name }}</strong><time>{{ new Date(item.created_at).toLocaleString() }}</time></header><p>{{ item.body }}</p></article></div><div v-else class="comment-empty">成为第一个留言的人。</div></section>
    </template>
  </div>
</template>

<style scoped>
.community-detail-page { max-width: 1120px; }.back-link { display: inline-flex; align-items: center; gap: 6px; margin-bottom: 26px; color: var(--color-primary); font-size: 14px; }.photo-gallery { display: grid; grid-template-columns: 1.5fr 1fr 1fr; grid-template-rows: repeat(2, 180px); gap: 8px; overflow: hidden; border-radius: var(--radius-card); background: var(--color-surface-soft); }.photo-gallery.single { display: block; max-height: 520px; }.photo-gallery img { width: 100%; height: 100%; display: block; object-fit: cover; }.photo-gallery img:first-child { grid-row: 1 / 3; }.photo-gallery.single img { max-height: 520px; object-fit: cover; }.story-layout { display: grid; grid-template-columns: minmax(0, 1fr) 152px; gap: 64px; margin-top: 48px; }.story-header { padding-bottom: 24px; border-bottom: 1px solid var(--color-border-soft); }.story-header h1 { margin: 0 0 12px; color: var(--color-ink); font-size: 28px; }.author-line { margin: 0; color: var(--color-muted); font-size: 14px; }.story-body { max-width: 760px; margin: 28px 0; white-space: pre-wrap; color: var(--color-body); font-size: 16px; line-height: 1.7; }.trip-facts { display: flex; flex-wrap: wrap; gap: 8px; padding-bottom: 28px; border-bottom: 1px solid var(--color-border-soft); }.trip-facts span { display: inline-flex; min-height: 36px; align-items: center; gap: 7px; padding: 7px 11px; border: 1px solid var(--color-border); border-radius: var(--radius-pill); color: var(--color-body); font-size: 13px; }.itinerary-section { padding-top: 32px; }.itinerary-section h2 { margin: 0 0 24px; color: var(--color-ink); font-size: 21px; }.day-row { display: grid; grid-template-columns: 145px minmax(0, 1fr); gap: 24px; padding: 22px 0; border-top: 1px solid var(--color-border-soft); }.day-row > div { display: grid; align-content: start; gap: 6px; }.day-row b { color: var(--color-primary); font-size: 12px; }.day-row span { color: var(--color-muted); font-size: 13px; }.day-row ol { display: grid; gap: 12px; margin: 0; padding: 0; list-style: none; }.day-row li { display: grid; grid-template-columns: 62px minmax(0, 1fr) auto; gap: 10px; align-items: baseline; font-size: 14px; }.day-row time, .day-row small { color: var(--color-muted); font-size: 12px; }.story-actions { display: grid; align-content: start; gap: 8px; }.story-actions button { display: flex; min-height: 44px; align-items: center; gap: 8px; padding: 0 10px; border: 1px solid var(--color-border); border-radius: var(--radius-control); color: var(--color-ink); background: var(--color-surface); font-size: 13px; }.story-actions button:hover, .story-actions button.active { border-color: var(--color-primary); color: var(--color-primary); }.story-actions button.danger:hover { border-color: var(--color-danger); color: var(--color-danger); }.comments-section { max-width: 760px; margin-top: 64px; padding-top: 32px; border-top: 1px solid var(--color-border-soft); }.comment-icon { color: var(--color-primary); }.comment-form { display: grid; gap: 12px; }.comment-form textarea { width: 100%; padding: 12px; border: 1px solid var(--color-border); border-radius: var(--radius-control); outline: 0; resize: vertical; color: var(--color-ink); background: var(--color-surface); }.comment-form textarea:focus { border-color: var(--color-ink); }.comment-form .primary-button { justify-self: start; }.comment-list { margin-top: 28px; border-top: 1px solid var(--color-border-soft); }.comment-list article { padding: 20px 0; border-bottom: 1px solid var(--color-border-soft); }.comment-list header { display: flex; justify-content: space-between; gap: 16px; }.comment-list strong { color: var(--color-ink); font-size: 14px; }.comment-list time { color: var(--color-muted); font-size: 12px; }.comment-list p { margin: 9px 0 0; color: var(--color-body); white-space: pre-wrap; }.comment-empty { padding: 32px 0; color: var(--color-muted); font-size: 14px; }@media (max-width: 744px) { .photo-gallery { grid-template-columns: 1fr 1fr; grid-template-rows: repeat(2, 150px); }.photo-gallery img:first-child { grid-column: 1 / 3; grid-row: auto; }.photo-gallery img:nth-child(n+4) { display: none; }.story-layout { grid-template-columns: 1fr; gap: 24px; margin-top: 32px; }.story-actions { grid-template-columns: repeat(4, minmax(0, 1fr)); position: static; }.story-actions button { justify-content: center; padding: 0; }.story-actions button span { display: none; }.story-actions .danger { grid-column: span 4; padding: 0 12px; }.story-actions .danger span { display: inline; }.day-row { grid-template-columns: 1fr; gap: 14px; }.comments-section { margin-top: 48px; }.comment-form .primary-button { width: 100%; } }
</style>
